package com.telecom.tollfree.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="telecom_numbers",indexes={@Index(name="ix_number_status",columnList="status"),@Index(name="ix_number_customer",columnList="customer_id")}) public class TelecomNumber { @Id @Column(name="number",length=20) private String number; @Enumerated(EnumType.STRING) @Column(nullable=false) private NumberStatus status=NumberStatus.AVAILABLE; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="customer_id") private Customer customer; @Version private long version; @Column(nullable=false) private Instant updatedAt=Instant.now(); protected TelecomNumber(){} public TelecomNumber(String n){number=n;} public String getNumber(){return number;} public NumberStatus getStatus(){return status;} public Customer getCustomer(){return customer;} public void transition(NumberStatus s){status=s;updatedAt=Instant.now();} public void assign(Customer c){customer=c;} public void clearCustomer(){customer=null;} }
